pattern_setting.create_sql:
CREATE TABLE IF NOT EXISTS pattern_setting (
    market INTEGER NOT NULL,
    analysis_period INTEGER NOT NULL,
    rate_threshold INTEGER NOT NULL,
    PRIMARY KEY (market)
);

volatility_stop_take_setting.create_sql:
CREATE TABLE IF NOT EXISTS volatility_stop_take_setting (
    market INTEGER NOT NULL,
    is_tick INTEGER NOT NULL,
    analysis_period INTEGER NOT NULL,
    PRIMARY KEY (market, is_tick)
);

v3k_feature_flags.create_sql:
CREATE TABLE IF NOT EXISTS v3k_feature_flags (
    name TEXT PRIMARY KEY,
    enabled INTEGER NOT NULL DEFAULT 0,
    updated_at TEXT,
    note TEXT
);
